import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#13
it('rejects an inherited required property', async () => {
  const registry = new ToolRegistry();
  let calls = 0;
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', required: ['location']}},
    async () => {
      calls += 1;
      return 'sunny';
    }
  );
  const input = Object.create({location: 'Paris'}) as Record<string, unknown>;
  const response = await registry.execute('weather', input);
  expect({result: response.result, calls}).toEqual({
    result: expect.stringMatching(/location.*required|required.*location/i),
    calls: 0,
  });
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.own-property.test.ts"
